`timescale 1ns / 1ps

module FU_ALU(
    input clk, EN,
    input[3:0] ALUControl,
    input[31:0] ALUA, ALUB,
    output[31:0] res,
    output zero, overflow,
    output finish
);

    reg state;
    assign finish = state == 1'b1;
    initial begin
        state = 0;
    end

    reg[3:0] ALUControl_reg;
    reg[31:0] ALUA_reg, ALUB_reg;

    always @(posedge clk) begin
        if (EN & ~state) begin
            ALUA_reg <= ALUA;
            ALUB_reg <= ALUB;
            ALUControl_reg <= ALUControl;
            state <= 1'b1;
        end
        else if (state) begin
            state <= 1'b0;
        end
    end

    reg[31:0] result;
    always @(*) begin
        case (ALUControl_reg)
            4'b0001: result = ALUA_reg + ALUB_reg;          // ADD/ADDI/AUIPC
            4'b0010: result = ALUA_reg - ALUB_reg;          // SUB
            4'b0011: result = ALUA_reg & ALUB_reg;          // AND
            4'b0100: result = ALUA_reg | ALUB_reg;          // OR
            4'b0101: result = ALUA_reg ^ ALUB_reg;          // XOR
            4'b0110: result = ALUA_reg << ALUB_reg[4:0];    // SLL
            4'b0111: result = ALUA_reg >> ALUB_reg[4:0];    // SRL
            4'b1000: result = ($signed(ALUA_reg) < $signed(ALUB_reg)) ? 32'd1 : 32'd0; // SLT
            4'b1001: result = (ALUA_reg < ALUB_reg) ? 32'd1 : 32'd0;                   // SLTU
            4'b1010: result = $signed(ALUA_reg) >>> ALUB_reg[4:0];                     // SRA
            4'b1011: result = ALUA_reg + 32'd4;             // A+4
            4'b1100: result = ALUB_reg;                     // LUI: B passthrough
            default: result = 32'b0;
        endcase
    end

    assign res = result;
    assign zero = ~|result;

    wire add_ovf = (ALUControl_reg == 4'b0001) & (~(ALUA_reg[31] ^ ALUB_reg[31]) & (result[31] ^ ALUA_reg[31]));
    wire sub_ovf = (ALUControl_reg == 4'b0010) & ((ALUA_reg[31] ^ ALUB_reg[31]) & (result[31] ^ ALUA_reg[31]));
    assign overflow = add_ovf | sub_ovf;

endmodule
