`timescale 1ns / 1ps

// Store / load-width test for FU_mem (verification only, lives in /tmp).
// Program (hand-assembled, rom.mem):
//   00: lui  x1, 0x12345      x1 = 0x12345000
//   04: addi x1, x1, 0x678    x1 = 0x12345678
//   08: sw   x1, 0(x0)        mem[0:3]  = 78 56 34 12
//   0c: sh   x1, 6(x0)        mem[6:7]  = 78 56
//   10: sb   x1, 9(x0)        mem[9]    = 78
//   14: lw   x2, 0(x0)        x2 = 0x12345678
//   18: lhu  x3, 6(x0)        x3 = 0x00005678
//   1c: lb   x4, 9(x0)        x4 = 0x00000078
//   20: lbu  x5, 1(x0)        x5 = 0x00000056
//   24: lh   x6, 2(x0)        x6 = 0x00001234
//   28: lb   x7, 3(x0)        x7 = 0x00000012
//   2c: jal  x0, 0            loop
module tbm;

    reg clk, rst;
    integer errors, idx;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0),
        .debug_data(), .wb_addr(), .wb_data(), .clk_counter(),
        .clk(clk), .rst(rst), .interrupter(1'b0)
    );

    initial begin clk = 0; forever #5 clk = ~clk; end
    initial begin rst = 1; errors = 0; idx = 0; #37 rst = 0; end

    reg[4:0]  exp_rd  [0:7];
    reg[31:0] exp_val [0:7];
    initial begin
        exp_rd[0] = 5'd1; exp_val[0] = 32'h1234_5000;
        exp_rd[1] = 5'd1; exp_val[1] = 32'h1234_5678;
        exp_rd[2] = 5'd2; exp_val[2] = 32'h1234_5678;
        exp_rd[3] = 5'd3; exp_val[3] = 32'h0000_5678;
        exp_rd[4] = 5'd4; exp_val[4] = 32'h0000_0078;
        exp_rd[5] = 5'd5; exp_val[5] = 32'h0000_0056;
        exp_rd[6] = 5'd6; exp_val[6] = 32'h0000_1234;
        exp_rd[7] = 5'd7; exp_val[7] = 32'h0000_0012;
    end

    always @(posedge clk) begin
        if (!rst && core.RegWrite_ctrl && core.rd_ctrl != 5'd0) begin
            $display("clk_cnt=%3d: x%0d <= 0x%08h",
                core.clk_counter, core.rd_ctrl, core.wt_data_WB);
            if (idx < 8) begin
                if (core.rd_ctrl != exp_rd[idx] || core.wt_data_WB !== exp_val[idx]) begin
                    $display("ERROR: [%0d] expected x%0d <= 0x%08h", idx,
                        exp_rd[idx], exp_val[idx]);
                    errors = errors + 1;
                end
            end
            idx = idx + 1;
        end
    end

    initial begin
        #3000;
        $display("mem[0..11] = %02h %02h %02h %02h %02h %02h %02h %02h %02h %02h %02h %02h",
            core.mem.ram.data[0], core.mem.ram.data[1], core.mem.ram.data[2],
            core.mem.ram.data[3], core.mem.ram.data[4], core.mem.ram.data[5],
            core.mem.ram.data[6], core.mem.ram.data[7], core.mem.ram.data[8],
            core.mem.ram.data[9], core.mem.ram.data[10], core.mem.ram.data[11]);
        if (core.mem.ram.data[0] !== 8'h78 || core.mem.ram.data[1] !== 8'h56 ||
            core.mem.ram.data[2] !== 8'h34 || core.mem.ram.data[3] !== 8'h12 ||
            core.mem.ram.data[6] !== 8'h78 || core.mem.ram.data[7] !== 8'h56 ||
            core.mem.ram.data[9] !== 8'h78) begin
            $display("ERROR: memory contents mismatch");
            errors = errors + 1;
        end
        if (idx < 8) begin
            $display("ERROR: only %0d/8 writes seen", idx);
            errors = errors + 1;
        end
        if (errors == 0) $display("RESULT: PASS");
        else             $display("RESULT: FAIL (%0d errors)", errors);
        $finish;
    end

endmodule
